WITH recent_accounts AS (SELECT *, CASE WHEN balance >= 81000 THEN 'High' WHEN balance >= 10000 THEN 'Medium' ELSE 'Low' END AS balance_tier FROM accounts WHERE balance > 69000), opened_year_summary AS (SELECT YEAR(opened_date) AS opened_year, status, SUM(CASE WHEN account_type = 'CHECKING' THEN balance ELSE 0 END) AS checking_balance, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(account_type))) AS account_type_values FROM recent_accounts GROUP BY YEAR(opened_date), status) SELECT opened_year, status, account_type_values FROM opened_year_summary ORDER BY opened_year DESC, status LIMIT 50;
